# PTX source for Swish activation (fp16 input/output)
PTX_SOURCE = r'''
.version 7.1
.target sm_80
.address_size 64

// Kernel: swish_kernel
.visible .entry swish_kernel (
    .param .u64 inp_ptr,
    .param .u64 out_ptr,
    .param .u32 N
)
{
    // Registers
    .reg .u64   %r_inp, %r_out, %r_idx, %r_stride, %r_addr;
    .reg .u32   %r_tid, %r_bid, %r_n, %r_tmp32;
    .reg .f16   %f_x, %f_res;
    .reg .f32   %f_x_f32, %f_neg, %f_tmp, %f_exp, %f_sig, %f_one;
    .reg .pred  %p_done;

    // Load parameters
    ld.param.u64    %r_inp, [inp_ptr];
    ld.param.u64    %r_out, [out_ptr];
    ld.param.u32    %r_n,   [N];

    // Thread identifiers
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_bid, %ctaid.x;
    mul.lo.u32 %r_idx, %r_bid, %ntid.x;
    add.u32 %r_idx, %r_idx, %r_tid;            // global linear thread id

    // Compute total stride = gridDim.x * blockDim.x
    mov.u32 %r_tmp32, %nctaid.x;               // gridDim.x
    mul.lo.u32 %r_stride, %r_tmp32, %ntid.x;   // stride

    // Loop over elements
LOOP:
    setp.ge.u32 %p_done, %r_idx, %r_n;
    @%p_done bra DONE;

    // Compute address: ptr + idx * sizeof(half) (2 bytes)
    shl.b64 %r_addr, %r_idx, 1;                // idx * 2
    add.u64 %r_addr, %r_inp, %r_addr;          // input address
    ld.global.u16 %r_tmp32, [%r_addr];         // load raw half bits
    mov.b16 %f_x, %r_tmp32;                    // move to f16 register

    // Convert to fp32 for math
    cvt.f32.f16 %f_x_f32, %f_x;

    // ---- sigmoid computation ----
    // sigmoid(x) = 1 / (1 + exp(-x))
    // exp(y) ≈ 2^{y * log2(e)} using ex2.approx
    neg.f32 %f_neg, %f_x_f32;                  // -x
    mul.f32 %f_tmp, %f_neg, 1.4426950408889634; // y * log2(e)
    ex2.approx.f32 %f_exp, %f_tmp;             // 2^{y*log2(e)} ≈ exp(y)

    // 1 + exp(-x)
    add.f32 %f_tmp, %f_exp, 1.0;               // 1 + exp(-x)

    // reciprocal => sigmoid
    rcp.approx.f32 %f_sig, %f_tmp;

    // ---- Swish: x * sigmoid(x) ----
    mul.f32 %f_tmp, %f_sig, %f_x_f32;          // x * sigmoid

    // Convert back to fp16 (round to nearest)
    cvt.rn.f16.f32 %f_res, %f_tmp;

    // Store result
    // Compute output address: out_ptr + idx * 2
    shl.b64 %r_addr, %r_idx, 1;
    add.u64 %r_addr, %r_out, %r_addr;
    mov.b16 %r_tmp32, %f_res;
    st.global.u16 [%r_addr], %r_tmp32;

    // Advance index
    add.u32 %r_idx, %r_idx, %r_stride;
    bra LOOP;

DONE:
    ret;
}
'''

class ModelNew:
    def __init__(self):
        # Load PTX module using the harness API
        self.module = ptx_load(PTX_SOURCE)
        self.kernel_name = "swish_kernel"

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        """
        Apply Swish activation to a half‑precision CUDA tensor using the PTX kernel.
        """
        assert x.is_cuda and x.dtype == torch.float16, "Input must be CUDA half tensor"
        y = torch.empty_like(x)

        total_elements = x.numel()
        block_size = 256
        grid_size = (total_elements + block_size - 1) // block_size

        # Arguments: input ptr, output ptr, total element count (uint32)
        args = [x.data_ptr(), y.data_ptr(), total_elements]

        # Launch kernel: (gridX, gridY, gridZ), (blockX, blockY, blockZ, sharedMem)
        ptx_launch(
            self.module,
            self.kernel_name,
            (grid_size, 1, 1),
            (block_size, 1, 1, 0),
            args
        )
        return y
